import {previewDocument,verify} from './preview.js';
import {helpPacket} from './privacy.js';
import {live,api,connect,refreshSession} from './live.js';
import {checkpoints, starter, broken, fixed, complete, alternative, binding, validate, snapshot, scriptKind, executableScript, propose, applyPlan, undoPlan} from './core.js';
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'▦',code:'〈〉',book:'▤',host:'◈',arrow:'↗',shield:'◇',play:'▷'};
let storageError=false;let saved; try { saved=JSON.parse(localStorage.getItem('rejoin.workspace')); if(saved) validate(saved.files); } catch { saved=null;storageError=true; }
let files=saved?.files || structuredClone(starter), protections=saved?.protections || ['style.css'], active='script.js', target='C2', verified=saved?.verified || null, plan=null, undo=saved?.undo || null, tab=new URLSearchParams(location.search).has('host')?'host':'workspace', panel='intro', lastResult=null, dirty=false;
let aiAdvice=null, aiJob=null;
try{localStorage.setItem('rejoin.preflight','1');localStorage.removeItem('rejoin.preflight');}catch{storageError=true;}
let saveState=storageError?'Storage unavailable — export to keep your work':'Saved on this device';
let history=Array.isArray(saved?.history)?saved.history.slice(-50):[],dismissedNote=saved?.dismissedNote||null,personal=false;
function record(outcome,details={}){history.push({id:crypto.randomUUID(),at:new Date().toISOString(),target,checkpoint:checkpoint(target).title,version:'1.1.0',outcome,...details});history=history.slice(-50);}
function positions(){return `Live: ${room.checkpoint} · Current revision verified: ${verified||'not yet'} · Recovery target: ${target}`;}
function syncStatus(){const state=$('#save-state');if(state)state.textContent=saveState;const pos=$('#positions');if(pos)pos.textContent=positions();document.querySelectorAll('[data-target]').forEach(el=>{const n=el.querySelector('.step-number');if(n)n.textContent=verified===el.dataset.target?'✓':String(Number(el.dataset.target.slice(1))).padStart(2,'0');});}
function invalidate(){verified=null;lastResult=null;plan=null;if(['done','plan'].includes(panel)){panel='intro';renderPanel();}syncStatus();}

let room={checkpoint:'C2',paused:false,connection:'Demo mode',channel:null}, checkGeneration=0;
const checkpoint=id=>checkpoints.find(c=>c.id===id);
function toast(message){ $('#toast').textContent=message; $('#toast').classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500); }
function save(){clearTimeout(save.timer);try{localStorage.setItem('rejoin.workspace',JSON.stringify({files,protections,verified,undo,history,dismissedNote}));dirty=false;saveState='Saved on this device';}catch{dirty=true;saveState='Save failed — export before leaving';toast('Save failed. Export your project before leaving this page.');}syncStatus();}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
function modal(html){$('#dialog').innerHTML=html;const heading=$('#dialog').querySelector('h2');if(heading){heading.id='dialog-title';$('#dialog').setAttribute('aria-labelledby','dialog-title');}$('#dialog').showModal();$('#dialog').querySelector('[data-close]')?.addEventListener('click',()=>$('#dialog').close());}
const button=(label,action,cls='')=>`<button class="${cls}" data-action="${action}">${label}</button>`;
function render(){
 const overlay=new URLSearchParams(location.search).has('overlay');
 if(overlay){$('#app').innerHTML=`<main class="overlay"><div class="brand"><b>↳</b> rejoin<span class="pill">${esc(room.connection)}</span></div><h1>Build something. Together.</h1><p>${esc(room.checkpoint)} · ${esc(checkpoint(room.checkpoint).title)}</p><small>Community RSVP workshop · ${room.optedIn||0} sharing · ${room.counts?Object.entries(room.counts).map(([key,count])=>esc(key)+': '+count).join(' · '):'Breakdown hidden until 5 learners opt in'}</small>${room.note?'<p>Teaching note · '+esc(room.noteCheckpoint||room.checkpoint)+': '+esc(room.note)+'</p>':''}</main>`;return;}
 $('#app').innerHTML=`<aside class="rail"><a class="brand-mark" href="/" aria-label="Rejoin home">↳</a><div class="rail-links">${[['workspace','code','Workspace'],['lesson','book','Lesson guide'],['host','host','Instructor view']].map(([t,i,n])=>`<button class="rail-btn ${tab===t?'selected':''}" data-tab="${t}" aria-label="${n}" title="${n}">${icons[i]}</button>`).join('')}</div><button class="rail-btn" data-action="privacy" title="Privacy and settings" aria-label="Privacy and settings">⚙</button><div class="avatar">A</div></aside>
 <div class="shell"><header><a href="/" class="wordmark">rejoin<span> / </span><small>workshop</small></a><div class="header-right"><span class="private">◇ Private workspace</span><button class="quiet" data-action="guide">Quick guide <span>↗</span></button>${button('Link Twitch & sharing','community','quiet')}</div></header>
 <main><div class="breadcrumb">COMMUNITY WORKSHOPS <span>/</span> BUILD ALONG</div><div class="page-heading"><div><h1>Your place in the stream.</h1><p>Keep building. Get unstuck. Make it yours.</p></div><div class="heading-actions">${button('↓ Export project','export','secondary')}${button('Watch on Twitch ↗','twitch','twitch-btn')}</div></div>
 <section class="stream-bar"><div class="stream-avatar">〈/〉<i></i></div><div class="stream-title"><strong>Build a community RSVP page</strong><span>HTML, CSS & JavaScript <b>·</b> Beginner friendly <b>·</b> Prepared workshop</span></div><span id="connection-badge" class="pill purple">${room.connection==='Connected'?'TWITCH CONNECTED':live.available?'PREPARED WORKSHOP':'DEMO WORKSHOP'}</span><div class="stream-current"><span>INSTRUCTOR CHECKPOINT</span><strong>${esc(room.checkpoint)} <b>·</b> ${esc(checkpoint(room.checkpoint).title)}</strong></div></section>
 <div id="room-notice">${roomNotice()}</div>${tab==='workspace'?workspace():tab==='lesson'?lesson():host()}
 <footer><span><i class="purple-dot"></i> ${esc(room.connection)} <span class="muted">·</span> ${room.paused?'Workshop paused':'Your code stays on this device'}</span><span>Made for the moments between “wait…” and “got it.” <b>↳</b></span></footer></main></div>`;
 bind(); if(tab==='workspace'){renderPanel(); updatePreview();}
}
function workspace(){return `<div class="checkpoint-strip">${checkpoints.map((c,i)=>`<button class="checkpoint ${target===c.id?'active':''}" data-target="${c.id}"><span class="step-number">${verified===c.id?'✓':String(i+1).padStart(2,'0')}</span><span><small>CHECKPOINT ${i+1}</small><strong>${c.title}</strong></span>${room.checkpoint===c.id?'<em>INSTRUCTOR</em>':''}${target===c.id?'<span class="target-dot">●</span>':''}</button>`).join('')}</div>
 <div class="work-layout"><section class="studio"><div class="studio-heading"><div><span class="tiny-icon">〈〉</span><strong>Your workspace</strong><span class="label">LOCAL</span></div><span id="save-state" role="status">${esc(saveState)}</span></div><div class="editor-toolbar"><div class="file-tabs">${Object.keys(files).map(f=>`<button class="file-tab ${active===f?'active':''}" data-file="${f}"><span class="file-icon ${f.endsWith('js')?'js':''}">${f.endsWith('js')?'JS':f.endsWith('css')?'#':'◇'}</span>${f}${protections.includes(f)?'<span class="lock">◇</span>':''}</button>`).join('')}</div><button data-action="protect" class="protect" aria-pressed="${protections.includes(active)}" title="Protect this file">◇ ${protections.includes(active)?'Protected':'Protect file'}</button></div><div class="editor"><div id="line-numbers" aria-hidden="true">${files[active].split('\n').map((_,i)=>`<span>${i+1}</span>`).join('')}</div><textarea id="code" spellcheck="false" aria-label="${active} source code" wrap="off">${esc(files[active])}</textarea></div><div class="editor-status"><span>${esc(active)} <b>·</b> UTF-8</span><span>Tab moves to next control <b>·</b> ${files[active].split('\n').length} lines</span></div>
 <div class="preview-toolbar"><strong><span>◉</span> Preview</strong><span class="preview-url">localhost / your-community</span><button data-action="run" class="quiet">↻ Run checks</button></div><div class="preview-wrap"><iframe id="preview" title="Isolated prepared workshop preview" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe></div><div class="preview-bottom"><span id="preview-state">Prepared-workshop preview</span><span>◇ Restricted execution</span></div></section>
 <aside class="recovery"><div class="recovery-top"><span class="spark">✧</span><strong>A little help, a lot more you.</strong><span class="label">REJOIN</span></div><div id="recovery-content"></div><div class="recovery-foot">◇ Your changes are yours. Always.</div></aside></div><div class="bottom-note"><span>◇ <strong>Your progress, at your pace.</strong> <span id="positions">${positions()}</span></span><div>${button('Download recovery receipt','receipt','quiet')}${button('Community & privacy','community','quiet')}${button('↶ Undo last fix','undo','quiet')}</div></div>`;}
function lesson(){return `<section class="guide-grid">${checkpoints.map(c=>`<article class="guide-card"><span class="pill purple">${c.id} · v1.1.0</span><h2>${c.title}</h2><p>${c.detail}</p><p>${c.id==='C1'?'Personalize the event title in index.html and the colors in style.css.':c.id==='C2'?'A function describes what should happen. An event listener decides when it happens. Connect the click to register.':'Use textContent to update the count after registration. The status region announces confirmation to screen readers.'}</p>${button('Practice this checkpoint →','practice-'+c.id,'primary')}</article>`).join('')}</section><div class="info-banner">A prepared, fictional community event. No registrations, email addresses or payments are collected.</div>`;}
function host(){if(live.available)return liveHost();return `<div class="host-grid"><section class="guide-card"><span class="eyebrow">INSTRUCTOR CONSOLE</span><h2>Keep your community together.</h2><p>Local controls are a rehearsal. With the connector running, authenticated broadcaster commands set the live checkpoint.</p><div class="host-controls">${checkpoints.map(c=>button(c.id+' · '+c.title,'host-'+c.id,'secondary')).join('')}</div>${button(room.paused?'Resume rehearsal':'Pause rehearsal','pause','secondary')}<div class="info-banner">${esc(room.connection)}. No live participant statistics are collected. Private code never appears here.</div></section><section class="guide-card"><span class="eyebrow">STREAM TOOLS</span><h2>Teach once. Help everyone.</h2><p><code>!checkpoint C2</code> Move the live checkpoint (host only).</p><p><code>!pause</code> Pause new recovery requests (host only).</p><p><code>!rejoin</code> Surface the public join route in the connector.</p><p class="muted">Learner identity linking and !stuck / !ready are not enabled in this build.</p><a class="primary link-button" href="/?overlay=1" target="_blank" rel="noopener">Open OBS overlay ↗</a></section></div><div class="guide-card"><h3>Privacy comes before a progress chart.</h3><p>0 shared progress reports. No public breakdown is shown without at least five opted-in learners. This build does not send learner progress.</p></div>`;}
function renderPanel(){const p=$('#recovery-content');if(!p)return;
 const intro=`<div class="orbit"><span>↳</span><i>✦</i><b>+</b></div><span class="eyebrow">A WAY BACK, NOT A START OVER</span><h2>Lost the thread?<br>Let’s pick it back up.</h2><p>A missing line shouldn’t mean losing your whole project. Find your next step and keep the parts that make it yours.</p><div class="target-card"><span>YOUR RECOVERY TARGET</span><strong><i>${target}</i> ${checkpoint(target).title}</strong><small>${checkpoint(target).detail}</small></div><div class="promise"><span>◇</span><div><strong>Keep your personal touches</strong><small>Your title, colors and protected files stay yours.</small></div></div>${button('✧ Help me continue →','help','primary full')}<small class="fineprint">${live.session?.aiConfigured?'AI help available with your permission':'Instructor-authored assistance · no code upload'}</small><div class="divider"></div><div class="mini-title">TAKE A DIFFERENT ROUTE</div>${button('Read the lesson guide <span>↗</span>','lesson','text-row')}${button('Prepare a question for the host <span>↗</span>','handoff','text-row')}`;
 if(panel==='intro')p.innerHTML=intro;
 else if(panel==='consent')p.innerHTML=`<span class="eyebrow">YOU’RE IN CONTROL</span><h2>Review what we’ll check.</h2><p>This prepared-workshop helper runs locally. These three files stay in this browser; no model or instructor receives them.</p><div class="review-files">${Object.keys(files).map(f=>`<div><span>${f}</span><small>${protections.includes(f)?'◇ Protected':'Read locally'}</small></div>`).join('')}</div><p class="fineprint">Supported: three UTF-8 HTML, CSS and JavaScript files, up to 100 KB each. Only prepared JavaScript patterns can run. Unfamiliar code remains editable and exportable.</p>${button('Show me an authored hint →','hint','primary full')}${live.session?.aiConfigured&&!personal?button('Ask AI about my code','ai-consent','secondary full'):''}${button('Cancel','cancel','quiet full')}`;
 else if(panel==='ai-wait')p.innerHTML=`<span class="eyebrow">AI ASSISTANCE</span><h2>Finding your<br>next step.</h2><p>Your captured script is being reviewed. You can keep editing; a suggestion for an older revision cannot be applied.</p><p>One request. 45-second timeout. No edits applied.</p>${button('Cancel AI request','ai-cancel','secondary full')}`;
 else if(panel==='ai-advice')p.innerHTML=`<span class="eyebrow">AI-GENERATED GUIDANCE · REVIEW IT</span><h2>One step at a time.</h2><div class="hint-box"><strong>Hint</strong><p>${esc(aiAdvice.hint)}</p></div><p>${esc(aiAdvice.explanation)}</p><ul class="check-list">${aiAdvice.evidence.map(e=>'<li>'+esc(e)+'</li>').join('')}</ul><p class="fineprint">Static evidence only. No behavioral checks have run from this request. AI may be wrong.</p>${button(aiAdvice.nextAction==='handoff'?'Prepare a host handoff':'Review a suggested fix →',aiAdvice.nextAction==='handoff'?'handoff':'suggest','primary full')}${button('Keep editing','cancel','quiet full')}`;
 else if(panel==='hint')p.innerHTML=`<span class="eyebrow">ONE SMALL NEXT STEP</span><h2>A function needs<br>an invitation.</h2><p>The <code>register()</code> function tells the page what to do. But what tells it <em>when</em> to do it?</p><div class="hint-box"><strong>Try this</strong><p>Find the button’s click event binding in <code>script.js</code>. Connect it to <code>register</code> without calling the function immediately.</p></div><p class="fineprint">${target==='C3'?'For C3, also update #count inside register().':''} This is an authored hint for the prepared defect, not an AI diagnosis.</p>${button('Review a suggested fix →','suggest','primary full')}${button('I’ll try it myself','cancel','quiet full')}`;
 else if(panel==='plan')p.innerHTML=`<div class="review-label">◇ REVIEW BEFORE APPLYING</div><h2>${plan.state==='candidate'?'A small fix.<br>Your project intact.':plan.state==='conflict'?'Your protection<br>comes first.':plan.state==='no-change'?'No rewrite needed.':'Let’s get another<br>pair of eyes.'}</h2>${plan.state==='candidate'?`<p>${target==='C2'?'Connect the button’s click event to your registration function.':'Connect registration and update the attendee count.'} Your HTML and CSS remain byte-for-byte unchanged.</p><div class="diff"><div>script.js <span>Proposed change</span></div><pre class="removed">− ${esc(plan.removed)}</pre><pre class="added">+ ${esc(plan.added)}</pre></div><details class="full-diff"><summary>Review exact file before and after</summary><strong>Before</strong><pre tabindex="0" aria-label="File before proposed change">${esc(JSON.parse(plan.before)['script.js'])}</pre><strong>After</strong><pre tabindex="0" aria-label="File after proposed change">${esc(plan.files['script.js'])}</pre></details><ul class="check-list"><li>◇ Event title unchanged</li><li>◇ Styles and colors unchanged</li><li>◇ Protected files untouched</li></ul><div class="check-result" id="candidate-result">${esc(lastResult?.message||'Behavioral checks have not run yet.')}</div>${button('Check suggestion','check-candidate','secondary full')}${button('Approve & apply this fix →','apply','primary full')}`:`<p>${esc(plan.message)}</p>${button('Prepare a help packet','handoff','primary full')}`} ${button('Back to my workspace','cancel','quiet full')}`;
 else if(panel==='done')p.innerHTML=`<div class="success-orbit">↳</div><span class="eyebrow">YOUR NEXT STEP IS WAITING</span><h2>${lastResult?.passed?'Back in the flow.':'Fix applied.<br>Checks need attention.'}</h2><p>${esc(lastResult?.message||'Run checks to confirm the result.')}</p><ul class="check-list"><li>◇ Your event title was preserved</li><li>◇ Your styles were preserved</li><li>↶ Your previous version is available</li></ul><div class="hint-box"><strong>A quick thought, if you like</strong><p>Why do we pass <code>register</code>, rather than <code>register()</code>, to the listener?</p>${button('Reveal explanation','answer','quiet')}</div>${button('Keep building →','cancel','primary full')}${button('Download recovery receipt','receipt','quiet full')}${button('Undo this fix','undo','quiet full')}`;
 p.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>action(el.dataset.action)));
}
function bind(){document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;render();});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelectorAll('[data-target]').forEach(el=>el.onclick=()=>{target=el.dataset.target;plan=null;panel='intro';render();});document.querySelectorAll('[data-file]').forEach(el=>el.onclick=()=>{active=el.dataset.file;render();});
 const code=$('#code');if(code){code.oninput=()=>{files[active]=code.value;dirty=true;saveState='Saving…';checkGeneration++;invalidate();$('#line-numbers').innerHTML=code.value.split('\n').map((_,i)=>`<span>${i+1}</span>`).join('');$('#save-state').textContent='Saving…';clearTimeout(save.timer);save.timer=setTimeout(save,300);};code.onscroll=()=>$('#line-numbers').scrollTop=code.scrollTop;}}
function action(a){if(a==='export'){save();download('rejoin-project.json',JSON.stringify({workshop:'community-rsvp-v1',files},null,2));toast('Project exported. Import it from Privacy & settings.');}
 else if(a==='help'){if(room.paused&&!personal){toast('Workshop paused. You can still edit and export.');return;}save();panel='consent';renderPanel();}
 else if(a==='hint'){panel='hint';renderPanel();}
 else if(a==='suggest'){try{if(aiAdvice&&aiAdvice.before!==snapshot(files))throw Error('Code changed since the AI review. Request fresh help.');plan=propose(files,target,protections);record('suggestion',{disposition:plan.state});save();lastResult=null;panel='plan';renderPanel();}catch(e){toast(e.message);}}
 else if(a==='cancel'){aiAdvice=null;panel='intro';plan=null;renderPanel();}
 else if(a==='check-candidate')checkCandidate();
 else if(a==='apply')apply();
 else if(a==='run')runChecks();
 else if(a==='protect'){protections=protections.includes(active)?protections.filter(x=>x!==active):[...protections,active];plan=null;panel='intro';save();render();}
 else if(a==='undo'){try{files=undoPlan(files,undo);record('undo');undo=null;verified=null;plan=null;panel='intro';save();render();toast('Previous version restored.');}catch(e){if(undo){modal(`<h2>Your newer edits are safe.</h2><p>${esc(e.message)}</p><button id="old-copy" class="primary">Download pre-fix copy</button><button data-close class="quiet">Close</button>`);$('#old-copy').onclick=()=>download('rejoin-before-fix.json',JSON.stringify({files:JSON.parse(undo.before)},null,2));}else toast('No fix to undo yet.');}}
 else if(a==='lesson'){tab='lesson';render();}
 else if(a.startsWith('practice-')){target=a.slice(9);tab='workspace';panel='intro';render();}
 else if(/^host-C[123]$/.test(a)){if(live.available){hostAction('checkpoint',{checkpoint:a.slice(5)});return;}if(room.connection==='Connected'){toast('Use your broadcaster chat command to change the live checkpoint.');return;}room.checkpoint=a.slice(5);render();}
 else if(a==='pause'){if(live.available){hostAction(room.paused?'resume':'pause');return;}if(room.connection==='Connected'){toast('Use !pause from your broadcaster account.');return;}room.paused=!room.paused;render();}
 else if(a==='answer')toast('Pass the function itself so it runs on click. register() would run immediately.');
 else if(a==='handoff')handoff();
 else if(a==='receipt')download('rejoin-recovery-receipt.json',JSON.stringify({workshop:'community-rsvp',version:'1.1.0',target:checkpoint(target),currentRevisionVerified:verified,attempts:history,unfinished:verified===target?'No outstanding prepared checks for this target':'Current revision still needs checking at '+target,undoAvailable:!!undo,recordedAt:new Date().toISOString(),notice:'Personal activity record; not proof of learning. No files or private questions included.'},null,2));
 else if(a==='dismiss-note'){dismissedNote=room.noteId||room.note;save();render();}
 else if(a==='continue-personal'){personal=true;panel='intro';render();toast('Personal practice: local checks and authored hints remain available.');}
 else if(a==='community')community();
 else if(a==='host-login')hostLogin();
 else if(a==='check-twitch')api('/api/twitch-check',{}).then(()=>toast('Twitch renewal validated with a real 401 recovery; reconnecting chat.')).catch(e=>toast(e.message));
 else if(a==='connect-twitch')api('/api/connect-twitch',{}).then(data=>location.assign(data.url)).catch(e=>toast(e.message));
 else if(a==='host-logout')api('/api/logout',{}).then(()=>refreshSession()).then(render).catch(e=>toast(e.message));
 else if(a==='host-note')hostNote();
 else if(a==='host-end')hostAction('end');
 else if(a==='chat-replies'){if(room.chatReplies)hostAction('chat-replies',{enabled:false});else{modal(`<h2>Reply to !rejoin in chat?</h2><p>This enables public replies containing only the workshop invitation link, at most once every 30 seconds. No learner information or code is posted.</p><button id="enable-replies" class="primary">Enable public chat replies</button><button data-close class="quiet">Cancel</button>`);$('#enable-replies').onclick=()=>{hostAction('chat-replies',{enabled:true});$('#dialog').close();};}}
 else if(a==='invite')navigator.clipboard.writeText(location.origin+'/?join=1').then(()=>toast('Learner invitation copied.')).catch(()=>toast(location.origin+'/?join=1'));
 else if(a==='ai-consent')aiConsent();
 else if(a==='ai-cancel')cancelAI();
 else if(a==='privacy')privacy();
 else if(a==='guide')modal(`<span class="eyebrow">WELCOME TO REJOIN</span><h2>A way back to building.</h2><ol><li>Personalize the event title or colors.</li><li>Use “Help me continue” for an authored hint.</li><li>Review and check the exact suggested fix.</li><li>Approve it. Try the RSVP button. Undo any time.</li></ol><p>Desktop is best for editing. Local saving is per browser: clearing storage removes progress. No cloud sync is enabled. ${live.session?.aiConfigured?'Optional AI help sends only the script and question you explicitly approve to OpenAI.':'AI is not configured; authored hints run locally.'}</p><button data-close class="primary">Let’s build</button>`);
 else if(a==='twitch'){if(room.channel)window.open('https://www.twitch.tv/'+encodeURIComponent(room.channel),'_blank','noopener');else modal(`<h2>Bring your stream.</h2><p>Enter a public channel name to watch alongside Rejoin. This does not connect EventSub. See README for the local connector setup.</p><label>Twitch channel<input id="channel" placeholder="your_channel" pattern="[A-Za-z0-9_]{1,25}"></label><button id="watch" class="primary">Open Twitch ↗</button><button data-close class="quiet">Cancel</button>`),!room.channel&&($('#watch').onclick=()=>{const c=$('#channel').value.trim();if(!/^[a-zA-Z0-9_]{1,25}$/.test(c)){toast('Enter a valid Twitch channel name.');return;}room.channel=c;$('#dialog').close();window.open('https://www.twitch.tv/'+c,'_blank','noopener');});}}
function privacy(){modal(`<span class="eyebrow">PRIVATE BY DEFAULT</span><h2>Your code. Your choice.</h2><p>Files and undo history are saved only in this browser. No code leaves your browser by default. Optional AI assistance sends only the script and question you approve to OpenAI. Optional community sharing sends a self-reported status, never code. The Twitch connector cannot access your files.</p><div class="settings-actions"><label>Import exported project<input id="import" type="file" accept=".json,application/json"></label><button id="delete" class="danger">Delete local workspace</button></div><p>Import replaces this workspace only after confirmation. Export first to keep a copy.</p><button data-close class="quiet">Close</button>`);$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('Project is larger than 1 MB.');const data=JSON.parse(await file.text());validate(data.files);if(!confirm('Replace this workspace with the imported project? Export first if you need the current version.'))return;files=data.files;undo=null;verified=null;plan=null;history=[];lastResult=null;panel='intro';save();$('#dialog').close();render();}catch(e){toast(e.message);}};$('#delete').onclick=async()=>{if(!confirm('Delete locally saved code and undo history? This cannot be undone.'))return;if(live.available){try{cancelAI();await api('/api/session',{},'DELETE');await refreshSession();}catch(e){toast('Server deletion failed: '+e.message);return;}}clearTimeout(save.timer);localStorage.removeItem('rejoin.workspace');files=structuredClone(starter);protections=['style.css'];history=[];dismissedNote=null;undo=null;verified=null;dirty=false;saveState='Fresh starter — not saved yet';panel='intro';plan=null;$('#dialog').close();render();toast('Local workspace deleted. A fresh unsaved starter is open.');};}
// Only known workshop scripts may execute. HTML is allowlisted; CSS is isolated by CSP.
function updatePreview(){const frame=$('#preview');if(!frame)return;try{frame.srcdoc=previewDocument(files);$('#preview-state').textContent=scriptKind(files['script.js'])==='unsupported'?'Custom JavaScript not executed · preview only':'Prepared-workshop preview · click to try';}catch(e){$('#preview-state').textContent=e.message;}}
async function runChecks(){save();updatePreview();const revision=snapshot(files), selected=target, gen=++checkGeneration;toast('Checking the prepared workshop…');const result=await verify(structuredClone(files),selected);if(gen!==checkGeneration||snapshot(files)!==revision||target!==selected){toast('Code or target changed. Run checks again.');return;}lastResult=result;verified=result.passed?selected:null;save();toast(result.message);const state=$('#preview-state');if(state)state.textContent=result.message;}
async function checkCandidate(){if(!plan||plan.state!=='candidate')return;const captured=plan;const result=await verify(captured.files,captured.target);if(plan!==captured||snapshot(files)!==captured.before){toast('This suggestion is stale. Request a fresh review.');return;}lastResult={...result,candidate:captured.after};record('candidate-checked',{passed:result.passed,checks:result.checks});save();renderPanel();}
async function apply(){if(room.paused&&!personal){toast('Workshop paused. Your suggestion has not been applied.');return;}try{if(!plan||!lastResult?.passed||lastResult.candidate!==plan.after){toast('Run the suggestion checks and resolve failures before applying.');return;}const approved=plan;files=applyPlan(files,approved);undo={before:approved.before,after:approved.after};verified=approved.target;record('approved',{changes:approved.added,changedFiles:['script.js'],preservedFiles:['index.html','style.css'],checks:lastResult.checks});panel='done';plan=null;save();render();toast('Approved fix applied. Your customizations are preserved.');}catch(e){toast(e.message);}}
render();
function updateRoom(next){
 if(!next){const footer=$('footer');if(footer)footer.firstElementChild.textContent='Connection interrupted · editing still works';return;}
 const old=room;room=next;
 const badge=$('#connection-badge');if(badge)badge.textContent=room.connection==='Connected'?'TWITCH CONNECTED':'PREPARED WORKSHOP';
 if(tab==='host'||new URLSearchParams(location.search).has('overlay')){render();return;}
 const current=$('.stream-current strong');if(current)current.textContent=room.checkpoint+' · '+checkpoint(room.checkpoint).title;
 const footer=$('footer');if(footer)footer.firstElementChild.textContent=room.connection+' · '+(room.ended?'Workshop ended':room.paused?'Workshop paused':'Private editing available');
 const note=$('#room-notice');if(note){note.innerHTML=roomNotice();note.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));}syncStatus();
 if(!room.ended&&personal){personal=false;toast('Live workshop resumed. Normal room controls apply.');}
 if(old.checkpoint!==room.checkpoint)toast('Instructor moved to '+room.checkpoint+'. Your recovery target is unchanged.');
}
if(new URLSearchParams(location.search).has('overlay')){
 fetch('/api/room').then(r=>r.ok?r.json():null).then(data=>{if(data){updateRoom(data);const source=new EventSource('/api/events');source.onmessage=e=>updateRoom(JSON.parse(e.data));source.onerror=()=>{$('.overlay small').textContent='Connection interrupted · progress may be stale';};}}).catch(()=>{});
}else connect(updateRoom,()=>{render();if(new URLSearchParams(location.search).has('join'))welcome();else if(new URLSearchParams(location.search).has('community'))community();else if(new URLSearchParams(location.search).has('authorize')){if(live.session.host)action('connect-twitch');else hostLogin();}});
function liveHost(){
 if(!live.session?.host)return `<section class="guide-card host-welcome"><span class="eyebrow">THE INSTRUCTOR DESK</span><h2>Lead the workshop.<br>Keep everyone in the loop.</h2><p>Sign in to advance the shared checkpoint, publish a note, pause recovery, and see anonymous opt-in progress.</p>${button('Instructor sign in →','host-login','primary')}<p class="fineprint">Learners do not need an instructor account. Your files stay private.</p></section>`;
 return `<div class="host-grid"><section class="guide-card"><span class="eyebrow">INSTRUCTOR · AUTHENTICATED</span><h2>Build together.<br>Keep your own pace.</h2><p>${room.ended?'Workshop ended':room.paused?'Workshop paused':'Workshop open'} · ${esc(room.connection)}</p><div class="host-controls">${checkpoints.map(c=>button(c.id+' · '+c.title,'host-'+c.id,'secondary')).join('')}</div>${button(room.paused?'Resume workshop':'Pause workshop','pause','secondary')} ${button('End workshop','host-end','quiet')}<div class="info-banner">Checkpoint changes reach connected learners without replacing their code or their recovery target.</div>${button('Publish a teaching note','host-note','secondary')} ${button('Authorize broadcaster chat','connect-twitch','secondary')} ${button('Check token renewal','check-twitch','secondary')}<p class="fineprint">Authorize the broadcaster account to enable automatic token renewal.</p></section><section class="guide-card"><span class="eyebrow">COMMUNITY PULSE</span><h2>${room.optedIn||0} learners sharing</h2><p>${room.participants||0} guest sessions · ${Math.max(0,(room.participants||0)-(room.optedIn||0))} unknown or private</p><div class="pulse-grid">${room.counts?Object.entries(room.counts).map(([key,count])=>'<div><strong>'+count+'</strong><span>'+esc(key)+'</span></div>').join(''):'<p>Breakdowns appear when at least five learners opt in. No one is ranked or identified.</p>'}</div><p class="fineprint">Self-reported readiness, not verified code or learning outcomes.</p><h3>Shared checkpoints</h3><p>${room.checkpoints?Object.entries(room.checkpoints).map(([id,n])=>esc(id)+': '+n).join(' · '):'Hidden until five learners opt in.'}</p><h3>Common blockers</h3><p>${Object.keys(room.blockers||{}).length?Object.entries(room.blockers).map(([key,n])=>esc(key)+': '+n).join(' · '):'No blocker group has five opted-in reports yet.'}</p><p>Last report: ${room.lastReportAt?esc(new Date(room.lastReportAt).toLocaleTimeString()):'None yet'}</p>${button('Copy learner invitation','invite','primary')} <a class="secondary link-button" href="/?overlay=1" target="_blank" rel="noopener">OBS overlay ↗</a></section></div><section class="guide-card"><h3>Stream commands</h3><p><code>!checkpoint C2</code> / <code>!pause</code> — broadcaster only.<br><code>!stuck</code> / <code>!ready</code> — linked learners who opted in.</p>${button(room.chatReplies?'Disable !rejoin replies':'Enable !rejoin chat replies','chat-replies','secondary')}<p class="fineprint">Replies are off by default. Requires a public HTTPS URL and user:write:chat scope.</p>${button('Sign out of instructor mode','host-logout','quiet')}</section>`;
}
function hostLogin(){modal(`<span class="eyebrow">INSTRUCTOR ACCESS</span><h2>Welcome back, host.</h2><p>Use the instructor password configured on this server.</p><form id="host-form"><label>Password<input type="password" id="host-password" autocomplete="current-password" required></label><button class="primary" type="submit">Sign in</button></form><button data-close class="quiet">Cancel</button>`);$('#host-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/login',{password:$('#host-password').value});await refreshSession();$('#dialog').close();render();if(new URLSearchParams(location.search).has('authorize'))action('connect-twitch');}catch(error){toast(error.message);}};}
async function hostAction(action,data={}){try{const result=await api('/api/host',{action,...data});updateRoom(result);}catch(e){toast(e.message);}}
function hostNote(){modal(`<h2>A note for everyone.</h2><p>Published to the room and overlay. Do not include private learner details.</p><label>Checkpoint<select id="note-checkpoint">${checkpoints.map(c=>`<option value="${c.id}" ${c.id===room.checkpoint?'selected':''}>${c.id} · ${c.title}</option>`).join('')}</select></label><label>Teaching note<textarea id="host-note" maxlength="800">${esc(room.note||'')}</textarea></label><button id="publish-note" class="primary">Publish note</button><button data-close class="quiet">Cancel</button>`);$('#publish-note').onclick=async()=>{await hostAction('note',{note:$('#host-note').value,checkpoint:$('#note-checkpoint').value});$('#dialog').close();};}
function community(){if(!live.available){toast('Community sharing needs the Rejoin server. This is the static demo.');return;}
 modal(`<span class="eyebrow">COMMUNITY, ON YOUR TERMS</span><h2>Share a signal.<br>Keep your code private.</h2><p>Send only a readiness status to your instructor. No files, name, or question is shared. Public breakdowns need at least five opted-in learners.</p><label class="check-label"><input type="checkbox" id="share-progress" ${live.session.share?'checked':''}> Share my self-reported progress</label><label>Your status<select id="progress"><option value="building">Building</option><option value="stuck">Could use help</option><option value="ready">Ready to continue</option><option value="unknown">Prefer not to say</option></select></label><label>Checkpoint<select id="progress-checkpoint">${checkpoints.map(c=>`<option value="${c.id}">${c.id} · ${c.title}</option>`).join('')}</select></label><label>Optional blocker<select id="progress-blocker"><option value="none">Prefer not to say</option><option value="binding">Button event binding</option><option value="count">Attendee count</option><option value="markup">Page structure</option><option value="protected">Protected-file conflict</option><option value="unsupported">Unsupported custom code</option></select></label><p>Sharing includes this checkpoint and category. No code or question is sent. Blocker groups smaller than five remain hidden.</p><button class="primary" id="save-progress">Save sharing choice</button><div class="divider"></div><p>${live.session.linked?'Twitch linked. Commands only update progress when sharing is enabled.':'Link your Twitch account to use !stuck and !ready. Linking alone does not enable sharing.'}</p><button id="twitch-link" class="secondary">${live.session.linked?'Unlink Twitch':'Link Twitch account'}</button><button data-close class="quiet">Close</button>`);
 $('#progress').value=live.session.progress;$('#progress-checkpoint').value=live.session.checkpoint||target;$('#progress-blocker').value=live.session.blocker||'none';
 $('#save-progress').onclick=async()=>{try{const data=await api('/api/progress',{share:$('#share-progress').checked,progress:$('#progress').value,checkpoint:$('#progress-checkpoint').value,blocker:$('#progress-blocker').value});Object.assign(live.session,data);toast(data.share?'Sharing enabled. Your code stays private.':'Progress sharing revoked.');$('#dialog').close();}catch(e){toast(e.message);}};
 $('#twitch-link').onclick=async()=>{try{if(live.session.linked){await api('/api/unlink',{});live.session.linked=false;community();}else{const data=await api('/api/link',{});location.assign(data.url);}}catch(e){toast(e.message);}};
}
function aiConsent(){modal(`<span class="eyebrow">REVIEW BEFORE SHARING</span><h2>Ask about this script.</h2><p>Only <strong>script.js</strong> and your question go through the Rejoin server to OpenAI. HTML, CSS, Twitch credentials and other learners are excluded. Rejoin does not save this request; provider retention policies still apply.</p><details><summary>Exact script to share</summary><pre class="consent-code">${esc(files['script.js'])}</pre></details><label>Your question<textarea id="ai-question" maxlength="1000" placeholder="Why doesn't my RSVP button do anything?"></textarea></label><label class="check-label"><input id="ai-agree" type="checkbox"> I approve sharing this script and question with OpenAI.</label><button id="ask-ai" class="primary">Ask AI</button><button data-close class="quiet">Keep it local</button>`);$('#ask-ai').onclick=()=>{if(!$('#ai-agree').checked){toast('Choose whether to share before continuing.');return;}const question=$('#ai-question').value||'Help me understand the next step for this checkpoint.';$('#dialog').close();askAI(question);};}
async function askAI(question){const captured=snapshot(files),selected=target;aiAdvice=null;const job={id:crypto.randomUUID(),controller:new AbortController()};aiJob=job;panel='ai-wait';renderPanel();
 try{const result=await api('/api/tutor',{id:job.id,consent:'ai-script-v1',script:files['script.js'],target:selected,question},'POST',job.controller.signal);
  if(aiJob!==job)return;if(captured!==snapshot(files)||selected!==target){panel='intro';renderPanel();toast('Your code or target changed. Request fresh AI guidance.');return;}
  aiAdvice={...result,before:captured};panel='ai-advice';renderPanel();
 }catch(e){if(aiJob===job){panel='hint';renderPanel();toast(e.name==='AbortError'?'AI request cancelled. Your code is unchanged.':e.message);}}finally{if(aiJob===job)aiJob=null;}}
function cancelAI(){if(!aiJob)return;const job=aiJob;aiJob=null;api('/api/tutor',{id:job.id},'DELETE').catch(()=>{});job.controller.abort();panel='intro';renderPanel();toast('AI request cancelled.');}
function welcome(){modal(`<span class="eyebrow">WELCOME TO THE WORKSHOP</span><h2>Start where you are.</h2><p>Your code stays in this browser. AI assistance and community progress sharing require separate permission. This workshop uses fictional event data and three HTML/CSS/JS files; each file is limited to 100 KB.</p><p>Instructor: ${room.checkpoint}. Full editing works best on desktop. Existing local work is always preserved.</p><label>Recovery target<select id="join-target">${checkpoints.map(c=>'<option value="'+c.id+'">'+c.id+' · '+c.title+'</option>').join('')}</select></label><button id="join-private" class="primary">Start privately →</button><button data-close class="quiet">Close</button>`);$('#join-target').value=room.checkpoint;$('#join-private').onclick=()=>{target=$('#join-target').value;$('#dialog').close();render();history.replaceState(null,'','/');};}

function handoff(){
 modal(`<span class="eyebrow">PRIVATE HANDOFF</span><h2>Review what you share.</h2><p>Select files, describe the problem, then review the exact redacted packet. Nothing is sent automatically. Recipients can keep downloaded copies; they cannot be revoked.</p><label>Your question<textarea id="question" maxlength="1000"></textarea></label><fieldset><legend>Files to include</legend>${Object.keys(files).map(name=>`<label class="check-label"><input type="checkbox" name="packet-file" value="${esc(name)}" ${name==='script.js'?'checked':''}> ${esc(name)}</label>`).join('')}</fieldset><button id="review-packet" class="primary">Review exact packet</button><button data-close class="quiet">Cancel</button>`);
 $('#review-packet').onclick=()=>{const {packet,redactions}=helpPacket({files,selected:[...document.querySelectorAll('[name="packet-file"]:checked')].map(e=>e.value),target,question:$('#question').value,checks:lastResult,history,version:'1.1.0'});const text=JSON.stringify(packet,null,2);modal(`<h2>Your exact help packet</h2><p>${redactions} possible secrets redacted. Detection is best effort: read the whole packet and remove any private details before sharing.</p><pre class="consent-code" tabindex="0" aria-label="Exact redacted help packet">${esc(text)}</pre><button id="packet" class="primary">Download reviewed packet</button><button id="packet-back" class="secondary">Change selection</button><button data-close class="quiet">Cancel</button>`);$('#packet').onclick=()=>{download('rejoin-help.json',text);$('#dialog').close();};$('#packet-back').onclick=handoff;};
}

function roomNotice(){const warning=storageError?'<div class="info-banner" role="alert">Browser storage is unavailable. Editing is temporary: export before leaving. Enable browser storage and reload to save locally.</div>':'';const ended=room.ended?`<section class="info-banner"><strong>The live workshop has ended.</strong><p>Your local work and lesson remain available. ${personal?'Personal practice is active: authored hints, local checks, undo and export work without AI.':'Start personal practice to finish with local checks and authored hints. AI requests are stopped.'}</p>${button('Continue in personal practice','continue-personal','secondary')}${button('Download recovery receipt','receipt','quiet')}</section>`:'';return warning+ended+(room.note&&dismissedNote!==(room.noteId||room.note)&&(!room.noteCheckpoint||room.noteCheckpoint===target)?`<aside class="info-banner"><strong>Instructor note · ${esc(room.noteCheckpoint||room.checkpoint)}</strong><p>${esc(room.note)}</p>${button('Dismiss note','dismiss-note','quiet')}</aside>`:'');}
